  feels_like: Float64;
}

enum Weather {
  Sunny(temp: Float64),
  Cloudy(coverage: Int),
  Rainy(mm_per_hour: Float64),
}

type Address = {
  street: Str;
  city: Str;
  zip: Str;
}

type Package = {
  tracking_id: Str;
  weight: Float64;
  destination: Address;
}

