fn Song.minutes(self) -> Float64 {
  return (duration_secs as Float64) / 60.0;
}

fn Weather.description(self) -> Str {
  match self {
    Sunny(temp) => { return "Sunny, " + temp + "\u00b0C"; }
    Cloudy(cov) => { return "Cloudy, " + cov + "% coverage"; }
    Rainy(mm) => { return "Rain, " + mm + "mm/hr"; }
  }
}

